import{_ as t,o as a,c as r,a4 as n}from"./chunks/framework.BybBnFXO.js";const p=JSON.parse('{"title":"Charge Transfer","description":"","frontmatter":{"title":"Charge Transfer","colorCause":"charge-transfer"},"headers":[],"relativePath":"classification/color-causes/charge-transfer.md","filePath":"classification/color-causes/charge-transfer.md","lastUpdated":1785925441000}'),o={name:"classification/color-causes/charge-transfer.md"};function s(i,e,d,l,c,h){return a(),r("div",null,[...e[0]||(e[0]=[n('<h1 id="charge-transfer" tabindex="-1">Charge Transfer <a class="header-anchor" href="#charge-transfer" aria-label="Permalink to &quot;Charge Transfer&quot;">​</a></h1><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>Charge transfer involves an electron hopping between adjacent ions or between different energy states of the same ion, driven by absorbed photons. Compared to d-d transitions, charge- transfer absorption is typically 10²–10⁴ times stronger, so even trace concentrations of the relevant elements can produce saturated, vivid colors. Subtypes include metal–metal (MMCT), oxygen–metal (OMCT), and metal–ligand (MLCT).</p><h2 id="mechanism" tabindex="-1">Mechanism <a class="header-anchor" href="#mechanism" aria-label="Permalink to &quot;Mechanism&quot;">​</a></h2><p><strong>Metal–metal CT (MMCT)</strong>: electron transfer between two adjacent metal ions. Classic example: Fe²⁺–Ti⁴⁺ in blue sapphire. Electron jumps from Fe to Ti, absorbing yellow-red light; transmitted light appears blue. <strong>Oxygen–metal CT (OMCT)</strong>: O²⁻ → metal ion (Fe³⁺, Mn⁴⁺, etc.). Often contributes alongside MMCT in blue and yellow sapphires. <strong>Metal–ligand CT (MLCT)</strong>: common in organic gem materials (e.g. pearl conchiolin).</p><h2 id="example-gemstones" tabindex="-1">Example Gemstones <a class="header-anchor" href="#example-gemstones" aria-label="Permalink to &quot;Example Gemstones&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Gem</th><th>Transfer Pair</th><th>Host</th><th>Color</th></tr></thead><tbody><tr><td>Blue Sapphire / 蓝宝石</td><td>Fe²⁺–Ti⁴⁺</td><td>Al₂O₃</td><td>blue</td></tr><tr><td>Amethyst / 紫晶</td><td>Fe²⁺ → Fe⁴⁺ (via O²⁻)</td><td>SiO₂</td><td>violet</td></tr><tr><td>Yellow Sapphire / 黄宝石</td><td>Fe³⁺–O²⁻</td><td>Al₂O₃</td><td>yellow</td></tr><tr><td>Aquamarine (deep) / 海蓝宝</td><td>Fe²⁺–Fe³⁺</td><td>Be₃Al₂Si₆O₁₈</td><td>deep blue</td></tr><tr><td>Hematite / 赤铁矿</td><td>Fe²⁺–Fe³⁺</td><td>Fe₂O₃</td><td>red-brown</td></tr><tr><td>Kunzite / 孔赛石</td><td>Mn²⁺ → Mn⁴⁺</td><td>LiAlSi₂O₆</td><td>pink (fades with light)</td></tr></tbody></table><p><em>See the <a href="./intro.html">color cause overview</a>.</em></p>',8)])])}const f=t(o,[["render",s]]);export{p as __pageData,f as default};
